"""Fixed reply texts (not generated by the AI). Edit freely.

Always Arabic, in a light Saudi "white" dialect,
friendly and clear, the same style as the AI's replies.
"""

# Sent when the AI can't answer (error, timeout, no API key...). The team follows up.
FALLBACK_REPLY = "شكراً لرسالتك! الفريق بيتواصل معك قريب إن شاء الله."

# Sent when a customer sends something we can't pass on to you (a sticker, a contact
# card...), or a photo/file that couldn't be forwarded to you.
NON_TEXT_REPLY = "شكراً لتواصلك! حالياً أقدر أقرأ الرسائل النصية فقط، ممكن تكتب سؤالك؟"

# Sent when a customer's photo, video, voice note, file or location was forwarded to you
# on Telegram. (The bot itself can't see or hear them.)
MEDIA_RECEIVED = {
    "image": "وصلتني الصورة، شكراً! بيطّلع عليها الفريق 🙏 وإذا عندك سؤال اكتبه لي هنا وأساعدك.",
    "video": "وصلني الفيديو، شكراً! بيطّلع عليه الفريق 🙏 وإذا عندك سؤال اكتبه لي هنا وأساعدك.",
    "audio": "وصلتني رسالتك الصوتية، شكراً! بيسمعها الفريق 🙏 وإذا تقدر تكتب سؤالك أساعدك على طول.",
    "document": "وصلني الملف، شكراً! بيطّلع عليه الفريق 🙏 وإذا عندك سؤال اكتبه لي هنا وأساعدك.",
    "location": "وصلني الموقع، شكراً! 🙏 وش الحي أو المنطقة اللي تدور فيها؟",
}


def media_received(msg_type: str) -> str:
    return MEDIA_RECEIVED.get(msg_type, MEDIA_RECEIVED["document"])
